-- Idempotent install for processes.executions
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS processes;

CREATE SEQUENCE IF NOT EXISTS processes.executions_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS processes.executions (
    row_id integer NOT NULL,
    process_id integer NOT NULL,
    step_id uuid NOT NULL,
    status text NOT NULL,
    started_at timestamp without time zone DEFAULT now() NOT NULL,
    completed_at timestamp without time zone DEFAULT now() NOT NULL,
    duration_ms integer DEFAULT 0 NOT NULL,
    row_count integer DEFAULT 0 NOT NULL,
    error_message text NOT NULL,
    entry_date timestamp without time zone DEFAULT now() NOT NULL,
    execution_key text
);

ALTER TABLE processes.executions ALTER COLUMN row_id SET DEFAULT nextval('processes.executions_row_id_seq'::regclass);
ALTER SEQUENCE processes.executions_row_id_seq OWNED BY processes.executions.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE processes.executions);
SELECT row_id, process_id, step_id, status, started_at, completed_at, duration_ms, row_count, error_message, entry_date, execution_key FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM processes.executions);
DROP TABLE _stg_load;

SELECT setval('processes.executions_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM processes.executions),1), (SELECT count(*) FROM processes.executions) > 0);
